/* ============================================================================
   14. TREATMENT_CATALOG — org-wide clinical reference data (Sprint 3 S3-A).
   NO price/cost/invoice columns (ADR-004): Clinical owns treatment IDENTITY;
   Finance will reference treatment_id later. RLS (0007): read all roles,
   write HQ only.
   ==========================================================================*/
export const treatmentCatalog = mysqlTable('treatment_catalog', {
  id: uuid('id').primaryKey().$defaultFn(() => randomUUID()),
  orgId: uuid('org_id').notNull(),
  code: varchar('code', { length: 32 }).notNull(),               /* TRT-#### */
  name: varchar('name', { length: 256 }).notNull(),
  category: varchar('category', { length: 64 }).notNull(),
  durationMin: integer('duration_min').notNull().default(30),
  /* Fasa 1A — Dr Partner's `xrayind`: this treatment normally needs an X-ray.
   * A FLAG, not a gate: it drives a prompt on the chart and an X-ray-expected
   * report, and never blocks anything. Clinics differ on which treatments
   * warrant imaging, and a hard gate here would be overruled by every dentist. */
  requiresXray: boolean('requires_xray').notNull().default(false),
  /* Fasa 1A — Dr Partner's `chartname`: which chart symbol this treatment
   * implies, so recording "Extraction" marks the tooth as extracted without a
   * second step. Soft reference by CODE (not FK) — a clinic may delete its own
   * symbol and the catalogue must not break; the chart falls back to the
   * condition. NULL = this treatment changes no symbol. */
  chartSymbolCode: varchar('chart_symbol_code', { length: 64 }),
  /* Fasa 1b — PRICING. Without these a treatment has no number, so every bill
   * totals RM0.00. All nullable: a treatment whose price is not yet known must
   * be representable, and `NULL` reads as "not filled in" whereas `0` would read
   * as "deliberately free". Prices are INTEGER sen, like `treatment_costs`, so a
   * tax percentage cannot introduce float drift.
   *
   * `panel_price` is its own amount rather than a discount percent because a
   * panel pays a DIFFERENT fee, not a fraction of the walk-in fee.
   * `classification_code` is LHDN's e-Invoice code — added now, while the table
   * is small, rather than after live billing rows exist. */
  price: integer('price'),
  price2: integer('price_2'),
  panelPrice: integer('panel_price'),
  cost: integer('cost'),
  localSstPct: numeric('local_sst_pct', { precision: 5, scale: 2 }),
  foreignerSstPct: numeric('foreigner_sst_pct', { precision: 5, scale: 2 }),
  classificationCode: varchar('classification_code', { length: 16 }),
  keyboardLetter: varchar('keyboard_letter', { length: 4 }),
  isActive: boolean('is_active').notNull().default(true),
  ...auditCols,
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('treatment_catalog_org_code_uq').on(t.orgId, t.code),
  index('treatment_catalog_org_cat_idx').on(t.orgId, t.category),
  check('treatment_catalog_duration_positive', sql`duration_min > 0`),
]);

