/* ============================================================================
   17. TOOTH_RECORDS — FDI chart snapshot per encounter. BOTH dentitions
   (permanent 11–48, deciduous 51–85) since Fasa 1A; the enum holds only the 7
   immutable CONDITIONS. Everything cosmetic and clinic-specific (bridge,
   denture, veneer, impacted, extracted, periapical, mobility) lives in
   `chart_symbols` and is referenced here by `symbol_code` — adding a symbol is
   then a ROW, not an enum migration.
   ==========================================================================*/
export const toothRecords = mysqlTable('tooth_records', {
  id: uuid('id').primaryKey().$defaultFn(() => randomUUID()),
  orgId: uuid('org_id').notNull(),
  branchId: uuid('branch_id').notNull().references(() => branches.id, { onDelete: 'restrict' }),
  patientId: uuid('patient_id').notNull().references(() => patients.id, { onDelete: 'restrict' }),
  encounterId: uuid('encounter_id').notNull().references(() => encounters.id, { onDelete: 'restrict' }),
  doctorId: uuid('doctor_id').notNull().references(() => staff.id, { onDelete: 'restrict' }),
  fdiNo: integer('fdi_no').notNull(),
  condition: toothConditionEnum('condition').notNull(),
  /* Fasa 1A — an ADDITIONAL finding laid over the condition (NULL = none).
   * Deliberately a varchar with NO FK: a clinic must be able to delete its own
   * symbol without orphaning historical charts, and the domain falls back to
   * the condition for an unknown code rather than throwing. */
  symbolCode: varchar('symbol_code', { length: 64 }),
  surfaces: jsonb('surfaces'),
  notes: varchar('notes', { length: 512 }),
  ...auditCols,
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('tooth_records_enc_tooth_uq').on(t.encounterId, t.fdiNo),
  index('tooth_records_patient_idx').on(t.patientId, t.fdiNo),
]);

