/* ============================================================================
   17b. PATIENT_ALLERGIES — the safety data the completion gate was missing.
   INSERT + RETIRE, never edit-in-place: an allergy is a FACT ABOUT A MOMENT,
   and silently rewriting one destroys the trail a clinical review needs.
   `retired_at` replaces DELETE so "this was believed once" stays readable.
   ==========================================================================*/
export const patientAllergies = mysqlTable('patient_allergies', {
  id: uuid('id').primaryKey().$defaultFn(() => randomUUID()),
  orgId: uuid('org_id').notNull(),
  branchId: uuid('branch_id').notNull().references(() => branches.id, { onDelete: 'restrict' }),
  patientId: uuid('patient_id').notNull().references(() => patients.id, { onDelete: 'restrict' }),
  allergen: varchar('allergen', { length: 256 }).notNull(),
  category: allergyCategoryEnum('category').notNull().default('drug'),
  severity: allergySeverityEnum('severity').notNull(),
  reaction: varchar('reaction', { length: 512 }),
  /* Who established this. Nullable because a clinic may migrate historical
   * allergies in without knowing the original author — refusing the row would
   * lose the allergy, which is worse than an unnamed source. */
  notedBy: uuid('noted_by').references(() => staff.id, { onDelete: 'restrict' }),
  notedAt: timestamp('noted_at', { withTimezone: true }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
  retiredAt: timestamp('retired_at', { withTimezone: true }),
  retiredBy: uuid('retired_by').references(() => staff.id, { onDelete: 'restrict' }),
  retiredReason: varchar('retired_reason', { length: 512 }),
  ...auditCols,
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [
  /* One ACTIVE record per allergen per patient. Retired rows are excluded so a
   * patient can be re-noted for the same allergen after a mistaken retire. */
  uniqueIndex('patient_allergies_active_uq').on(t.patientId, t.allergen, t.retiredAt),
  index('patient_allergies_patient_idx').on(t.patientId, t.retiredAt),
  index('patient_allergies_branch_idx').on(t.branchId),
]);

