/* ============================================================================
   FASA 5E — WhatsApp opt-out (STOP list).

   A patient who replies "STOP" must never be blasted again. This is not a
   courtesy feature: continuing to message someone who asked to stop is a PDPA
   problem for a clinic and, operationally, the fastest way to be reported and
   have the number restricted by Meta.

   Keyed on the PHONE NUMBER, not the patient record, for two reasons:
     - the blast path works from a raw number list, so the lookup must be cheap
       and exact without joining patients;
     - a patient may have no `patients` row (a lead, a guardian's number, a
       former patient whose record was archived) and their STOP must still count.

   Deliberately ORG-WIDE, not per branch: "stop" means stop messaging me, not
   stop messaging me from this one clinic. A patient who opts out at Setia
   Tropika must not be re-contacted by Bukit Indah.
   ==========================================================================*/
export const waOptOuts = mysqlTable('wa_opt_outs', {
  id: uuid('id').primaryKey().$defaultFn(() => randomUUID()),
  orgId: uuid('org_id').notNull(),
  /** Normalised digits-only phone (see normalizePhone). Unique per org. */
  phone: varchar('phone', { length: 64 }).notNull(),
  /** How the opt-out was recorded. */
  source: waOptOutSourceEnum('source').notNull().default('reply_stop'),
  /** The exact words that triggered it, for audit ("STOP", "berhenti", …). */
  matchedKeyword: varchar('matched_keyword', { length: 64 }),
  /** Free-text note when staff add it manually. */
  reason: varchar('reason', { length: 512 }),
  /** Branch where the request arrived; informational only — the block is org-wide. */
  originBranchId: uuid('origin_branch_id').references(() => branches.id, { onDelete: 'set null' }),
  /** Patient resolved at the time, when one could be matched. */
  patientId: uuid('patient_id'),
  /** Set when the patient asks to receive messages again. */
  revokedAt: timestamp('revoked_at', { withTimezone: true }),
  revokedBy: uuid('revoked_by'),
  ...auditCols,
  deletedAt: timestamp('deleted_at', { withTimezone: true }),
}, (t) => [
  uniqueIndex('wa_opt_outs_phone_uq').on(t.orgId, t.phone),
  index('wa_opt_outs_active_idx').on(t.orgId, t.deletedAt),
]);

