/* 7.13 AI_APPROVAL_REQUESTS — the QUEUE behind an APPROVAL_REQUIRED verdict.
 *
 * ai_approval_rules DECLARES that an action needs approval; this records the
 * actual held action so a human can decide it. Without this table the verdict
 * was a dead end: the caller held the conversation and nobody could approve
 * anything.
 *
 * `payload` is a SMALL summary of what was proposed (e.g. the drafted message),
 * not a copy of the domain's records — the owning domain stays the source of
 * truth. `payload` and `note` may contain patient text, so this table is
 * HQ-only and an operator may clear a row. */
export const aiApprovalRequestStatusEnum = (columnName: string) =>
  mysqlEnum(columnName, ['pending', 'approved', 'rejected', 'cancelled'] as const);

export const aiApprovalRequests = mysqlTable('ai_approval_requests', {
  id: uuid('id').primaryKey().$defaultFn(() => randomUUID()),
  orgId: uuid('org_id').notNull(),
  /* Nullable: the policy verdict may be reached without a resolved agent row. */
  agentId: uuid('agent_id').references(() => aiAgents.id, { onDelete: 'set null' }),
  /* Denormalised so the queue still reads correctly if an agent is renamed or
   * soft-deleted — a request is a record of what happened at the time. */
  agentKey: varchar('agent_key', { length: 64 }).notNull(),
  domain: varchar('domain', { length: 32 }).notNull(),
  actionKey: varchar('action_key', { length: 128 }).notNull(),
  risk: aiRiskLevelEnum('risk').notNull(),
  /* Why the engine held it (the PolicyResult.reason) — the audit trail's why. */
  reason: text('reason').notNull(),
  /* A small proposed-action summary. Never a copy of domain records. */
  payload: jsonb('payload'),
  status: aiApprovalRequestStatusEnum('status').notNull().default('pending'),
  requestedBy: uuid('requested_by'),
  decidedBy: uuid('decided_by'),
  decidedAt: timestamp('decided_at', { withTimezone: true }),
  decisionNote: text('decision_note'),
  ...auditCols,
}, (t) => [
  index('ai_approval_requests_org_status_idx').on(t.orgId, t.status, t.createdAt),
  index('ai_approval_requests_org_created_idx').on(t.orgId, t.createdAt),
]);

export type AiApprovalRequest = typeof aiApprovalRequests.$inferSelect;
export type AiApprovalRequestStatus = (typeof aiApprovalRequests.$inferSelect)['status'];

