/* 7.12 AI_WHATSAPP_SETTINGS — anti-ban pacing + escalation, per org+branch.
 * Owned by AI Manager; the WhatsApp Hub reads these to show the effective
 * limits, so an operator tunes them in one place and both surfaces agree. */
export const aiWhatsappSettings = mysqlTable('ai_whatsapp_settings', {
  orgId: uuid('org_id').notNull(),
  branchId: uuid('branch_id').notNull(),
  /* Anti-ban — send pacing (mirrors the D18 warm-up rules in the worker). */
  antibanEnabled: boolean('antiban_enabled').notNull().default(true),
  /* AI replies for this branch. DELIBERATELY SEPARATE from antiban_enabled, which
   * controls whether the anti-ban BRAKES are applied — turning that one off makes
   * the account more aggressive. Two different switches, two different names. */
  aiEnabled: boolean('ai_enabled').notNull().default(true),
  minDelaySeconds: integer('min_delay_seconds').notNull().default(30),
  maxDelaySeconds: integer('max_delay_seconds').notNull().default(60),
  dailyMessageCap: integer('daily_message_cap').notNull().default(50),
  hourlyMessageCap: integer('hourly_message_cap').notNull().default(10),
  warmupDays: integer('warmup_days').notNull().default(7),
  warmupDailyCap: integer('warmup_daily_cap').notNull().default(20),
  /* FASA 5D-C — how long a patient may wait for a human before the clinic sees
   * a red mark. A setting, not a constant: clinics differ in how fast they can
   * realistically answer. */
  slaMinutes: integer('sla_minutes').notNull().default(15),
  /* Escalation — when AI hands the conversation to a human. */
  escalationKeywords: text('escalation_keywords').notNull(),
  maxAiTurns: integer('max_ai_turns').notNull().default(3),
  escalateOnAiUncertainty: boolean('escalate_on_ai_uncertainty').notNull().default(true),
  escalationReply: text('escalation_reply').notNull(),
  updatedBy: uuid('updated_by'),
  createdAt: timestamp('created_at', { withTimezone: true }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
  updatedAt: timestamp('updated_at', { withTimezone: true }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
}, (t) => [
  primaryKey({ columns: [t.orgId, t.branchId], name: 'ai_whatsapp_settings_pk' }),
]);

