/* ==========================================================================
   FASA 5D-B — WA_NOTIFICATIONS
   The queue named 'notifications' existed and was never used, and there was no
   table behind it: an event had nowhere to land. A notification is durable state
   the operator reads later (the bell must show what is unread after a reload),
   so it is a table, not just a queue message.
   Coalescing lives in occurrenceCount: one row per (kind, scope) inside a
   window, rather than one row per event.
   ========================================================================== */
export const waNotifications = mysqlTable('wa_notifications', {
  id: uuid('id').primaryKey().$defaultFn(() => randomUUID()),
  orgId: uuid('org_id').notNull(),
  /* Nullable: an org-wide event has no single branch. */
  branchId: uuid('branch_id'),
  kind: varchar('kind', { length: 32 }).notNull(),
  severity: varchar('severity', { length: 16 }).notNull().default('info'),
  title: varchar('title', { length: 255 }).notNull(),
  body: varchar('body', { length: 512 }).notNull(),
  /* The record this is about, when it names one (a stopped channel, one blast).
   * Empty for aggregated kinds, where the count is the message. */
  entityId: varchar('entity_id', { length: 64 }),
  entityType: varchar('entity_type', { length: 48 }),
  /* How many events this row represents. */
  occurrenceCount: integer('occurrence_count').notNull().default(1),
  firstAt: timestamp('first_at', { withTimezone: false }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
  lastAt: timestamp('last_at', { withTimezone: false }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
  readAt: timestamp('read_at', { withTimezone: false }),
  readBy: uuid('read_by'),
  deletedAt: timestamp('deleted_at', { withTimezone: false }),
  /* Identity of the row while it is UNREAD, NULL once read.
   *
   * Exists only to give the atomic merge something to collide on: a unique
   * index on this column means "at most one unread row per (org, branch, kind,
   * entity)". Read rows fall out of the constraint on their own because NULLs
   * do not collide — which is precisely the rule "an event after a read starts a
   * fresh row". Without it, raise() had to select-then-insert, and two events
   * arriving together produced either duplicate rows or (worse) a single row
   * that had lost some of their counts.
   *
   * Defined in migration 0013; declared here so the schema and the database do
   * not drift. */
  unreadKey: varchar('unread_key', { length: 191 }).generatedAlwaysAs(
    sql`CASE WHEN read_at IS NULL AND deleted_at IS NULL
             THEN CONCAT(org_id, '|', COALESCE(branch_id, ''), '|', kind, '|', COALESCE(entity_id, ''))
             ELSE NULL END`,
    { mode: 'stored' },
  ),
  createdAt: timestamp('created_at', { withTimezone: false }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
  updatedAt: timestamp('updated_at', { withTimezone: false }).notNull().default(sql`CURRENT_TIMESTAMP(6)`),
}, (t) => [
  /* The bell's query: unread for this scope, newest first. */
  index('wa_notifications_bell_idx').on(t.orgId, t.branchId, t.readAt, t.lastAt),
  /* The coalescing lookup: the open notification of this kind for this scope. */
  index('wa_notifications_coalesce_idx').on(t.orgId, t.branchId, t.kind, t.entityId, t.readAt),
  /* The atomic merge target — see the unreadKey note above. */
  uniqueIndex('wa_notifications_unread_uidx').on(t.unreadKey),
]);

export type WaNotification = typeof waNotifications.$inferSelect;



/* ============================================================================
 * 7.13 WAITLIST + APPOINTMENT REMINDERS — FASA E (0027)
 *
 * Waitlist mirrors the reference system's model: a registered patient who
 * could not get a slot says WHEN they would come (days + a broad time of
 * day, never an hour — the waitlist is a WISH, the hour comes from whatever
 * slot opens). Booking AI offers these entries when a cancellation frees a
 * matching slot (sender lands with E6, once a live WhatsApp number exists).
 *
 * Reminders are the schedule a future cron drains: one row = one planned
 * nudge for one appointment (same-morning / day-before / an extra layer for
 * high no-show risk). appointment_id CASCADES because a reminder is future
 * work owned by its appointment, not a historical record.
 * ========================================================================== */

export const waitlistStatusEnum = (columnName: string) =>
  mysqlEnum(columnName, ['active', 'notified', 'booked', 'cancelled', 'expired'] as const);
export const preferredTimeEnum = (columnName: string) =>
  mysqlEnum(columnName, ['morning', 'afternoon', 'evening'] as const);

